(window.ABDI_PAKET = window.ABDI_PAKET || {})["skb.ti.bilangan.1"] = [{"i":4840,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Bilangan biner 111001₂ jika diubah ke basis 8 (oktal) adalah …","e":"Konsep: satu digit oktal tepat sama dengan 3 bit, jadi konversinya per kelompok tanpa lewat desimal.\n1. Kelompokkan 3 bit dari kanan: 111 001 (tambahkan 0 di kiri bila kurang).\n2. Ubah tiap kelompok: 111 = 7, 001 = 1.\nJawaban: 71₈.\nCara cepat: hafalkan tabel 3 bit (000 sampai 111 = 0 sampai 7), lalu ubah per kelompok.","o":["72₈","17₈","70₈","71₈","73₈"],"s":[0,0,0,1,0],"w":["Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Biner, oktal, dan heksadesimal bisa dikonversi per kelompok bit (3 bit untuk oktal, 4 bit untuk heksadesimal)."},{"i":4841,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Bilangan heksadesimal 1D0₁₆ jika diubah ke basis 10 (desimal) adalah …","e":"Konsep: nilai bilangan basis 16 = jumlah tiap digit dikali 16 pangkat posisinya (posisi paling kanan pangkat 0).\n1. 1×16² + 13×16¹ + 0×16⁰ = 256 + 208 + 0 = 464.\nJawaban: 464₁₀.\nCara cepat: hafalkan pangkat 2 (1, 2, 4, 8, 16, 32, 64, 128, 256, 512) dan pangkat 16 (1, 16, 256, 4.096), lalu jumlahkan bobot digit yang tidak nol.","o":["463₁₀","462₁₀","465₁₀","464₁₀","466₁₀"],"s":[0,0,0,1,0],"w":["Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Kalikan tiap digit dengan pangkat basisnya dari kanan (pangkat 0, 1, 2, …), lalu jumlahkan."},{"i":4842,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Representasi komplemen dua 8 bit untuk bilangan −66 adalah …","e":"Konsep: komplemen dua untuk bilangan negatif: tulis nilai positifnya dalam biner, balik semua bit, lalu tambah 1.\n1. 66 dalam 8 bit: 01000010\n2. Balik semua bit (komplemen satu): 10111101\n3. Tambah 1: 10111110\nJawaban: 10111110.\nCara cepat: dari kanan, salin bit sampai bertemu angka 1 pertama (ikut disalin), lalu balik semua bit di kirinya.","o":["10111111","10111101","01000010","10111110","11000010"],"s":[0,0,0,1,0],"w":["Selisih 1: angka 1 ditambahkan dua kali.","Itu komplemen satu (semua bit dibalik) yang belum ditambah 1.","Itu 66 positif; tanda minusnya belum diproses.","Bit dibalik semua lalu ditambah 1.","Itu cara tanda-besaran (sign-magnitude): bit kiri 1 lalu nilai biasa, bukan komplemen dua."],"h":"Tulis nilai positifnya dalam 8 bit, balik semua bit, lalu tambah 1."},{"i":4843,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Bilangan biner 1011000₂ jika diubah ke basis 8 (oktal) adalah …","e":"Konsep: satu digit oktal tepat sama dengan 3 bit, jadi konversinya per kelompok tanpa lewat desimal.\n1. Kelompokkan 3 bit dari kanan: 001 011 000 (tambahkan 0 di kiri bila kurang).\n2. Ubah tiap kelompok: 001 = 1, 011 = 3, 000 = 0.\nJawaban: 130₈.\nCara cepat: hafalkan tabel 3 bit (000 sampai 111 = 0 sampai 7), lalu ubah per kelompok.","o":["131₈","127₈","126₈","132₈","130₈"],"s":[0,0,0,0,1],"w":["Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah."],"h":"Biner, oktal, dan heksadesimal bisa dikonversi per kelompok bit (3 bit untuk oktal, 4 bit untuk heksadesimal)."},{"i":4844,"k":"skb.ti.bilangan","j":"pilgan","v":3,"q":"Bilangan heksadesimal 4AC₁₆ jika diubah ke basis 10 (desimal) adalah …","e":"Konsep: nilai bilangan basis 16 = jumlah tiap digit dikali 16 pangkat posisinya (posisi paling kanan pangkat 0).\n1. 4×16² + 10×16¹ + 12×16⁰ = 1024 + 160 + 12 = 1196.\nJawaban: 1196₁₀.\nCara cepat: hafalkan pangkat 2 (1, 2, 4, 8, 16, 32, 64, 128, 256, 512) dan pangkat 16 (1, 16, 256, 4.096), lalu jumlahkan bobot digit yang tidak nol.","o":["6911₁₀","1195₁₀","1198₁₀","1197₁₀","1196₁₀"],"s":[0,0,0,0,1],"w":["Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah."],"h":"Kalikan tiap digit dengan pangkat basisnya dari kanan (pangkat 0, 1, 2, …), lalu jumlahkan."},{"i":4845,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Bilangan oktal 54₈ jika diubah ke basis 2 (biner) adalah …","e":"Konsep: satu digit oktal tepat sama dengan 3 bit, jadi konversinya per kelompok tanpa lewat desimal.\n1. Ubah tiap digit menjadi 3 bit: 5 = 101, 4 = 100.\n2. Gabungkan, lalu buang angka 0 di paling depan.\nJawaban: 101100₂.\nCara cepat: hafalkan tabel 3 bit (000 sampai 111 = 0 sampai 7), lalu ubah per kelompok.","o":["1010100₂","101011₂","101100₂","110110₂","101101₂"],"s":[0,0,1,0,0],"w":["Ini hasil bila 54₈ keliru dibaca sebagai basis 16.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah.","Ini hasil bila 54₈ keliru dibaca sebagai basis 10.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Biner, oktal, dan heksadesimal bisa dikonversi per kelompok bit (3 bit untuk oktal, 4 bit untuk heksadesimal)."},{"i":4846,"k":"skb.ti.bilangan","j":"pilgan","v":3,"q":"Bilangan desimal 3318₁₀ jika diubah ke basis 8 (oktal) adalah …","e":"Konsep: desimal ke basis 8: bagi terus dengan 8, catat sisanya, lalu baca sisa dari bawah ke atas.\n1. 3318 : 8 = 414 sisa 6\n2. 414 : 8 = 51 sisa 6\n3. 51 : 8 = 6 sisa 3\n4. 6 : 8 = 0 sisa 6\n5. Baca sisa dari bawah ke atas.\nJawaban: 6366₈.\nCara cepat: cari kelipatan 8 terbesar yang muat, lalu sisa pembagiannya menjadi digit terakhir.","o":["31430₈","6367₈","6636₈","6365₈","6366₈"],"s":[0,0,0,0,1],"w":["Ini hasil bila 3318₁₀ keliru dibaca sebagai basis 16.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah."],"h":"Bagi berulang dengan 8 dan baca sisanya dari bawah ke atas."},{"i":4847,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Bilangan biner 100111₂ jika diubah ke basis 8 (oktal) adalah …","e":"Konsep: satu digit oktal tepat sama dengan 3 bit, jadi konversinya per kelompok tanpa lewat desimal.\n1. Kelompokkan 3 bit dari kanan: 100 111 (tambahkan 0 di kiri bila kurang).\n2. Ubah tiap kelompok: 100 = 4, 111 = 7.\nJawaban: 47₈.\nCara cepat: hafalkan tabel 3 bit (000 sampai 111 = 0 sampai 7), lalu ubah per kelompok.","o":["51₈","50₈","47₈","74₈","46₈"],"s":[0,0,1,0,0],"w":["Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Biner, oktal, dan heksadesimal bisa dikonversi per kelompok bit (3 bit untuk oktal, 4 bit untuk heksadesimal)."},{"i":4848,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Bilangan biner 11000₂ jika diubah ke basis 8 (oktal) adalah …","e":"Konsep: satu digit oktal tepat sama dengan 3 bit, jadi konversinya per kelompok tanpa lewat desimal.\n1. Kelompokkan 3 bit dari kanan: 011 000 (tambahkan 0 di kiri bila kurang).\n2. Ubah tiap kelompok: 011 = 3, 000 = 0.\nJawaban: 30₈.\nCara cepat: hafalkan tabel 3 bit (000 sampai 111 = 0 sampai 7), lalu ubah per kelompok.","o":["27₈","26₈","30₈","31₈","32₈"],"s":[0,0,1,0,0],"w":["Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Biner, oktal, dan heksadesimal bisa dikonversi per kelompok bit (3 bit untuk oktal, 4 bit untuk heksadesimal)."},{"i":4849,"k":"skb.ti.bilangan","j":"pilgan","v":3,"q":"Bilangan 8 bit 10000010 dalam format komplemen dua bernilai desimal …","e":"Konsep: pada komplemen dua 8 bit, bit paling kiri bernilai −128. Nilai = −128 + jumlah bobot bit lainnya.\n1. Bit paling kiri 1, jadi bilangannya negatif.\n2. Balik semua bit: 01111101\n3. Tambah 1: 01111110 = 126\n4. Jadi nilainya −126.\nJawaban: −126.\nCara cepat: hitung langsung: −128 + 2 = −126.","o":["−125","126","130","−126","−2"],"s":[0,0,0,1,0],"w":["Itu cara membaca komplemen satu: setelah bit dibalik, masih harus ditambah 1.","Bit paling kiri 1, jadi bilangannya negatif.","Itu nilai bila bit dibaca tanpa tanda (unsigned).","Bit kiri 1 berarti negatif; dibalik lalu ditambah 1 memberi besarnya.","Itu cara tanda-besaran: bit kiri hanya dianggap tanda, sisanya dibaca biasa."],"h":"Bit paling kiri pada komplemen dua 8 bit berbobot −128; bit lain berbobot positif seperti biasa."},{"i":4850,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Bilangan biner 11101101₂ jika diubah ke basis 10 (desimal) adalah …","e":"Konsep: nilai bilangan basis 2 = jumlah tiap digit dikali 2 pangkat posisinya (posisi paling kanan pangkat 0).\n1. 1×2⁷ + 1×2⁶ + 1×2⁵ + 0×2⁴ + 1×2³ + 1×2² + 0×2¹ + 1×2⁰ = 128 + 64 + 32 + 0 + 8 + 4 + 0 + 1 = 237.\nJawaban: 237₁₀.\nCara cepat: hafalkan pangkat 2 (1, 2, 4, 8, 16, 32, 64, 128, 256, 512) dan pangkat 16 (1, 16, 256, 4.096), lalu jumlahkan bobot digit yang tidak nol.","o":["238₁₀","239₁₀","236₁₀","732₁₀","237₁₀"],"s":[0,0,0,0,1],"w":["Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Sesuai hasil konversi langkah demi langkah."],"h":"Kalikan tiap digit dengan pangkat basisnya dari kanan (pangkat 0, 1, 2, …), lalu jumlahkan."},{"i":4851,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Bilangan desimal 183₁₀ jika diubah ke basis 16 (heksadesimal) adalah …","e":"Konsep: desimal ke basis 16: bagi terus dengan 16, catat sisanya, lalu baca sisa dari bawah ke atas.\n1. 183 : 16 = 11 sisa 7\n2. 11 : 16 = 0 sisa 11 (= B)\n3. Baca sisa dari bawah ke atas.\nJawaban: B7₁₆.\nCara cepat: cari kelipatan 16 terbesar yang muat, lalu sisa pembagiannya menjadi digit terakhir.","o":["B7₁₆","183₁₆","7B₁₆","B6₁₆","B8₁₆"],"s":[1,0,0,0,0],"w":["Sesuai hasil konversi langkah demi langkah.","Ini hasil bila 183₁₀ keliru dibaca sebagai basis 16.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Bagi berulang dengan 16 dan baca sisanya dari bawah ke atas."},{"i":4852,"k":"skb.ti.bilangan","j":"pilgan","v":3,"q":"Bilangan 8 bit 10010011 dalam format komplemen dua bernilai desimal …","e":"Konsep: pada komplemen dua 8 bit, bit paling kiri bernilai −128. Nilai = −128 + jumlah bobot bit lainnya.\n1. Bit paling kiri 1, jadi bilangannya negatif.\n2. Balik semua bit: 01101100\n3. Tambah 1: 01101101 = 109\n4. Jadi nilainya −109.\nJawaban: −109.\nCara cepat: hitung langsung: −128 + 19 = −109.","o":["−108","147","−19","−109","109"],"s":[0,0,0,1,0],"w":["Itu cara membaca komplemen satu: setelah bit dibalik, masih harus ditambah 1.","Itu nilai bila bit dibaca tanpa tanda (unsigned).","Itu cara tanda-besaran: bit kiri hanya dianggap tanda, sisanya dibaca biasa.","Bit kiri 1 berarti negatif; dibalik lalu ditambah 1 memberi besarnya.","Bit paling kiri 1, jadi bilangannya negatif."],"h":"Bit paling kiri pada komplemen dua 8 bit berbobot −128; bit lain berbobot positif seperti biasa."},{"i":4853,"k":"skb.ti.bilangan","j":"pilgan","v":3,"q":"Bilangan oktal 1160₈ jika diubah ke basis 2 (biner) adalah …","e":"Konsep: satu digit oktal tepat sama dengan 3 bit, jadi konversinya per kelompok tanpa lewat desimal.\n1. Ubah tiap digit menjadi 3 bit: 1 = 001, 1 = 001, 6 = 110, 0 = 000.\n2. Gabungkan, lalu buang angka 0 di paling depan.\nJawaban: 1001110000₂.\nCara cepat: hafalkan tabel 3 bit (000 sampai 111 = 0 sampai 7), lalu ubah per kelompok.","o":["1001110000₂","10010001000₂","1000101100000₂","1001110001₂","1001101111₂"],"s":[1,0,0,0,0],"w":["Sesuai hasil konversi langkah demi langkah.","Ini hasil bila 1160₈ keliru dibaca sebagai basis 10.","Ini hasil bila 1160₈ keliru dibaca sebagai basis 16.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Biner, oktal, dan heksadesimal bisa dikonversi per kelompok bit (3 bit untuk oktal, 4 bit untuk heksadesimal)."},{"i":4854,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Representasi komplemen dua 8 bit untuk bilangan −89 adalah …","e":"Konsep: komplemen dua untuk bilangan negatif: tulis nilai positifnya dalam biner, balik semua bit, lalu tambah 1.\n1. 89 dalam 8 bit: 01011001\n2. Balik semua bit (komplemen satu): 10100110\n3. Tambah 1: 10100111\nJawaban: 10100111.\nCara cepat: dari kanan, salin bit sampai bertemu angka 1 pertama (ikut disalin), lalu balik semua bit di kirinya.","o":["10100110","10100111","11011001","10101000","01011001"],"s":[0,1,0,0,0],"w":["Itu komplemen satu (semua bit dibalik) yang belum ditambah 1.","Bit dibalik semua lalu ditambah 1.","Itu cara tanda-besaran (sign-magnitude): bit kiri 1 lalu nilai biasa, bukan komplemen dua.","Selisih 1: angka 1 ditambahkan dua kali.","Itu 89 positif; tanda minusnya belum diproses."],"h":"Tulis nilai positifnya dalam 8 bit, balik semua bit, lalu tambah 1."},{"i":4855,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Bilangan desimal 404₁₀ jika diubah ke basis 8 (oktal) adalah …","e":"Konsep: desimal ke basis 8: bagi terus dengan 8, catat sisanya, lalu baca sisa dari bawah ke atas.\n1. 404 : 8 = 50 sisa 4\n2. 50 : 8 = 6 sisa 2\n3. 6 : 8 = 0 sisa 6\n4. Baca sisa dari bawah ke atas.\nJawaban: 624₈.\nCara cepat: cari kelipatan 8 terbesar yang muat, lalu sisa pembagiannya menjadi digit terakhir.","o":["426₈","2004₈","404₈","625₈","624₈"],"s":[0,0,0,0,1],"w":["Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Ini hasil bila 404₁₀ keliru dibaca sebagai basis 16.","Ini hasil bila 404₁₀ keliru dibaca sebagai basis 8.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah."],"h":"Bagi berulang dengan 8 dan baca sisanya dari bawah ke atas."},{"i":4856,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Bilangan biner 10100₂ jika diubah ke basis 10 (desimal) adalah …","e":"Konsep: nilai bilangan basis 2 = jumlah tiap digit dikali 2 pangkat posisinya (posisi paling kanan pangkat 0).\n1. 1×2⁴ + 0×2³ + 1×2² + 0×2¹ + 0×2⁰ = 16 + 0 + 4 + 0 + 0 = 20.\nJawaban: 20₁₀.\nCara cepat: hafalkan pangkat 2 (1, 2, 4, 8, 16, 32, 64, 128, 256, 512) dan pangkat 16 (1, 16, 256, 4.096), lalu jumlahkan bobot digit yang tidak nol.","o":["18₁₀","19₁₀","20₁₀","22₁₀","21₁₀"],"s":[0,0,1,0,0],"w":["Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Kalikan tiap digit dengan pangkat basisnya dari kanan (pangkat 0, 1, 2, …), lalu jumlahkan."},{"i":4857,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Bilangan biner 1010101₂ jika diubah ke basis 10 (desimal) adalah …","e":"Konsep: nilai bilangan basis 2 = jumlah tiap digit dikali 2 pangkat posisinya (posisi paling kanan pangkat 0).\n1. 1×2⁶ + 0×2⁵ + 1×2⁴ + 0×2³ + 1×2² + 0×2¹ + 1×2⁰ = 64 + 0 + 16 + 0 + 4 + 0 + 1 = 85.\nJawaban: 85₁₀.\nCara cepat: hafalkan pangkat 2 (1, 2, 4, 8, 16, 32, 64, 128, 256, 512) dan pangkat 16 (1, 16, 256, 4.096), lalu jumlahkan bobot digit yang tidak nol.","o":["87₁₀","86₁₀","58₁₀","85₁₀","84₁₀"],"s":[0,0,0,1,0],"w":["Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Sesuai hasil konversi langkah demi langkah.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Kalikan tiap digit dengan pangkat basisnya dari kanan (pangkat 0, 1, 2, …), lalu jumlahkan."},{"i":4858,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Bilangan biner 10010111₂ jika diubah ke basis 16 (heksadesimal) adalah …","e":"Konsep: satu digit heksadesimal tepat sama dengan 4 bit, jadi konversinya per kelompok tanpa lewat desimal.\n1. Kelompokkan 4 bit dari kanan: 1001 0111 (tambahkan 0 di kiri bila kurang).\n2. Ubah tiap kelompok: 1001 = 9, 0111 = 7.\nJawaban: 97₁₆.\nCara cepat: hafalkan tabel 4 bit (0000 sampai 1111 = 0 sampai F), lalu ubah per kelompok.","o":["79₁₆","99₁₆","97₁₆","96₁₆","98₁₆"],"s":[0,0,1,0,0],"w":["Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Biner, oktal, dan heksadesimal bisa dikonversi per kelompok bit (3 bit untuk oktal, 4 bit untuk heksadesimal)."},{"i":4859,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Representasi komplemen dua 8 bit untuk bilangan −98 adalah …","e":"Konsep: komplemen dua untuk bilangan negatif: tulis nilai positifnya dalam biner, balik semua bit, lalu tambah 1.\n1. 98 dalam 8 bit: 01100010\n2. Balik semua bit (komplemen satu): 10011101\n3. Tambah 1: 10011110\nJawaban: 10011110.\nCara cepat: dari kanan, salin bit sampai bertemu angka 1 pertama (ikut disalin), lalu balik semua bit di kirinya.","o":["11100010","01100010","10011111","10011110","10011101"],"s":[0,0,0,1,0],"w":["Itu cara tanda-besaran (sign-magnitude): bit kiri 1 lalu nilai biasa, bukan komplemen dua.","Itu 98 positif; tanda minusnya belum diproses.","Selisih 1: angka 1 ditambahkan dua kali.","Bit dibalik semua lalu ditambah 1.","Itu komplemen satu (semua bit dibalik) yang belum ditambah 1."],"h":"Tulis nilai positifnya dalam 8 bit, balik semua bit, lalu tambah 1."},{"i":4860,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Bilangan oktal 361₈ jika diubah ke basis 2 (biner) adalah …","e":"Konsep: satu digit oktal tepat sama dengan 3 bit, jadi konversinya per kelompok tanpa lewat desimal.\n1. Ubah tiap digit menjadi 3 bit: 3 = 011, 6 = 110, 1 = 001.\n2. Gabungkan, lalu buang angka 0 di paling depan.\nJawaban: 11110001₂.\nCara cepat: hafalkan tabel 3 bit (000 sampai 111 = 0 sampai 7), lalu ubah per kelompok.","o":["10001111₂","101101001₂","1101100001₂","11110001₂","11110010₂"],"s":[0,0,0,1,0],"w":["Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Ini hasil bila 361₈ keliru dibaca sebagai basis 10.","Ini hasil bila 361₈ keliru dibaca sebagai basis 16.","Sesuai hasil konversi langkah demi langkah.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Biner, oktal, dan heksadesimal bisa dikonversi per kelompok bit (3 bit untuk oktal, 4 bit untuk heksadesimal)."},{"i":4861,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Bilangan biner 1010010₂ jika diubah ke basis 16 (heksadesimal) adalah …","e":"Konsep: satu digit heksadesimal tepat sama dengan 4 bit, jadi konversinya per kelompok tanpa lewat desimal.\n1. Kelompokkan 4 bit dari kanan: 0101 0010 (tambahkan 0 di kiri bila kurang).\n2. Ubah tiap kelompok: 0101 = 5, 0010 = 2.\nJawaban: 52₁₆.\nCara cepat: hafalkan tabel 4 bit (0000 sampai 1111 = 0 sampai F), lalu ubah per kelompok.","o":["53₁₆","25₁₆","51₁₆","52₁₆","54₁₆"],"s":[0,0,0,1,0],"w":["Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Biner, oktal, dan heksadesimal bisa dikonversi per kelompok bit (3 bit untuk oktal, 4 bit untuk heksadesimal)."},{"i":4862,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Bilangan desimal 326₁₀ jika diubah ke basis 8 (oktal) adalah …","e":"Konsep: desimal ke basis 8: bagi terus dengan 8, catat sisanya, lalu baca sisa dari bawah ke atas.\n1. 326 : 8 = 40 sisa 6\n2. 40 : 8 = 5 sisa 0\n3. 5 : 8 = 0 sisa 5\n4. Baca sisa dari bawah ke atas.\nJawaban: 506₈.\nCara cepat: cari kelipatan 8 terbesar yang muat, lalu sisa pembagiannya menjadi digit terakhir.","o":["507₈","1446₈","506₈","326₈","605₈"],"s":[0,0,1,0,0],"w":["Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Ini hasil bila 326₁₀ keliru dibaca sebagai basis 16.","Sesuai hasil konversi langkah demi langkah.","Ini hasil bila 326₁₀ keliru dibaca sebagai basis 8.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar."],"h":"Bagi berulang dengan 8 dan baca sisanya dari bawah ke atas."},{"i":4863,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Hasil operasi bitwise 10100010 OR 10011101 adalah …","e":"Konsep: operasi bitwise dikerjakan per kolom bit, tidak ada simpanan (carry). OR: hasilnya 1 jika salah satu bit 1.\n1. Bilangan pertama: 10100010\n2. Bilangan kedua: 10011101\n3. Hasil per kolom (OR): 10111111\nJawaban: 10111111.\nCara cepat: tulis kedua bilangan bertumpuk, lalu periksa kolom demi kolom dari kiri.","o":["00111111","10111111","10101111","10000000","01000000"],"s":[0,1,0,0,0],"w":["Itu hasil XOR (hasilnya 1 jika kedua bit berbeda), bukan OR.","Dihitung per kolom: hasilnya 1 jika salah satu bit 1.","Bit ke-4 dari kiri salah dihitung.","Itu hasil AND (hasilnya 1 hanya jika kedua bit 1), bukan OR.","Itu kebalikan (NOT) dari jawaban; aturan bitnya terbalik."],"h":"Tulis kedua bilangan bertumpuk dan kerjakan kolom demi kolom. Ingat aturan OR: hasilnya 1 jika salah satu bit 1."},{"i":4864,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Bilangan desimal 21₁₀ jika diubah ke basis 16 (heksadesimal) adalah …","e":"Konsep: desimal ke basis 16: bagi terus dengan 16, catat sisanya, lalu baca sisa dari bawah ke atas.\n1. 21 : 16 = 1 sisa 5\n2. 1 : 16 = 0 sisa 1\n3. Baca sisa dari bawah ke atas.\nJawaban: 15₁₆.\nCara cepat: cari kelipatan 16 terbesar yang muat, lalu sisa pembagiannya menjadi digit terakhir.","o":["21₁₆","16₁₆","15₁₆","51₁₆","11₁₆"],"s":[0,0,1,0,0],"w":["Ini hasil bila 21₁₀ keliru dibaca sebagai basis 16.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Ini hasil bila 21₁₀ keliru dibaca sebagai basis 8."],"h":"Bagi berulang dengan 16 dan baca sisanya dari bawah ke atas."},{"i":4865,"k":"skb.ti.bilangan","j":"pilgan","v":3,"q":"Bilangan desimal 493₁₀ jika diubah ke basis 2 (biner) adalah …","e":"Konsep: desimal ke basis 2: bagi terus dengan 2, catat sisanya, lalu baca sisa dari bawah ke atas.\n1. 493 : 2 = 246 sisa 1\n2. 246 : 2 = 123 sisa 0\n3. 123 : 2 = 61 sisa 1\n4. 61 : 2 = 30 sisa 1\n5. 30 : 2 = 15 sisa 0\n6. 15 : 2 = 7 sisa 1\n7. 7 : 2 = 3 sisa 1\n8. 3 : 2 = 1 sisa 1\n9. 1 : 2 = 0 sisa 1\n10. Baca sisa dari bawah ke atas.\nJawaban: 111101101₂.\nCara cepat: untuk biner, kurangi dengan pangkat 2 terbesar yang muat (128, 64, 32, …) dan tulis 1 di posisi yang dipakai, 0 di yang dilewati.","o":["111101101₂","101101111₂","10010010011₂","111101100₂","111101110₂"],"s":[1,0,0,0,0],"w":["Sesuai hasil konversi langkah demi langkah.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Ini hasil bila 493₁₀ keliru dibaca sebagai basis 16.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Bagi berulang dengan 2 dan baca sisanya dari bawah ke atas."},{"i":4866,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Hasil operasi bitwise 10011101 AND 00000011 adalah …","e":"Konsep: operasi bitwise dikerjakan per kolom bit, tidak ada simpanan (carry). AND: hasilnya 1 hanya jika kedua bit 1.\n1. Bilangan pertama: 10011101\n2. Bilangan kedua: 00000011\n3. Hasil per kolom (AND): 00000001\nJawaban: 00000001.\nCara cepat: tulis kedua bilangan bertumpuk, lalu periksa kolom demi kolom dari kiri.","o":["10011110","00010001","11111110","10011111","00000001"],"s":[0,0,0,0,1],"w":["Itu hasil XOR (hasilnya 1 jika kedua bit berbeda), bukan AND.","Bit ke-4 dari kiri salah dihitung.","Itu kebalikan (NOT) dari jawaban; aturan bitnya terbalik.","Itu hasil OR (hasilnya 1 jika salah satu bit 1), bukan AND.","Dihitung per kolom: hasilnya 1 hanya jika kedua bit 1."],"h":"Tulis kedua bilangan bertumpuk dan kerjakan kolom demi kolom. Ingat aturan AND: hasilnya 1 hanya jika kedua bit 1."},{"i":4867,"k":"skb.ti.bilangan","j":"pilgan","v":3,"q":"Bilangan 8 bit 11001101 dalam format komplemen dua bernilai desimal …","e":"Konsep: pada komplemen dua 8 bit, bit paling kiri bernilai −128. Nilai = −128 + jumlah bobot bit lainnya.\n1. Bit paling kiri 1, jadi bilangannya negatif.\n2. Balik semua bit: 00110010\n3. Tambah 1: 00110011 = 51\n4. Jadi nilainya −51.\nJawaban: −51.\nCara cepat: hitung langsung: −128 + 77 = −51.","o":["−50","51","−51","205","−77"],"s":[0,0,1,0,0],"w":["Itu cara membaca komplemen satu: setelah bit dibalik, masih harus ditambah 1.","Bit paling kiri 1, jadi bilangannya negatif.","Bit kiri 1 berarti negatif; dibalik lalu ditambah 1 memberi besarnya.","Itu nilai bila bit dibaca tanpa tanda (unsigned).","Itu cara tanda-besaran: bit kiri hanya dianggap tanda, sisanya dibaca biasa."],"h":"Bit paling kiri pada komplemen dua 8 bit berbobot −128; bit lain berbobot positif seperti biasa."},{"i":4868,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Hasil operasi bitwise 00000111 OR 11011110 adalah …","e":"Konsep: operasi bitwise dikerjakan per kolom bit, tidak ada simpanan (carry). OR: hasilnya 1 jika salah satu bit 1.\n1. Bilangan pertama: 00000111\n2. Bilangan kedua: 11011110\n3. Hasil per kolom (OR): 11011111\nJawaban: 11011111.\nCara cepat: tulis kedua bilangan bertumpuk, lalu periksa kolom demi kolom dari kiri.","o":["00000110","11001111","11011001","11011111","00100000"],"s":[0,0,0,1,0],"w":["Itu hasil AND (hasilnya 1 hanya jika kedua bit 1), bukan OR.","Bit ke-4 dari kiri salah dihitung.","Itu hasil XOR (hasilnya 1 jika kedua bit berbeda), bukan OR.","Dihitung per kolom: hasilnya 1 jika salah satu bit 1.","Itu kebalikan (NOT) dari jawaban; aturan bitnya terbalik."],"h":"Tulis kedua bilangan bertumpuk dan kerjakan kolom demi kolom. Ingat aturan OR: hasilnya 1 jika salah satu bit 1."},{"i":4869,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Bilangan heksadesimal 38₁₆ jika diubah ke basis 2 (biner) adalah …","e":"Konsep: satu digit heksadesimal tepat sama dengan 4 bit, jadi konversinya per kelompok tanpa lewat desimal.\n1. Ubah tiap digit menjadi 4 bit: 3 = 0011, 8 = 1000.\n2. Gabungkan, lalu buang angka 0 di paling depan.\nJawaban: 111000₂.\nCara cepat: hafalkan tabel 4 bit (0000 sampai 1111 = 0 sampai F), lalu ubah per kelompok.","o":["110111₂","111001₂","111000₂","111010₂","100110₂"],"s":[0,0,1,0,0],"w":["Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Ini hasil bila 38₁₆ keliru dibaca sebagai basis 10."],"h":"Biner, oktal, dan heksadesimal bisa dikonversi per kelompok bit (3 bit untuk oktal, 4 bit untuk heksadesimal)."},{"i":4870,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Bilangan heksadesimal 2B₁₆ jika diubah ke basis 10 (desimal) adalah …","e":"Konsep: nilai bilangan basis 16 = jumlah tiap digit dikali 16 pangkat posisinya (posisi paling kanan pangkat 0).\n1. 2×16¹ + 11×16⁰ = 32 + 11 = 43.\nJawaban: 43₁₀.\nCara cepat: hafalkan pangkat 2 (1, 2, 4, 8, 16, 32, 64, 128, 256, 512) dan pangkat 16 (1, 16, 256, 4.096), lalu jumlahkan bobot digit yang tidak nol.","o":["43₁₀","42₁₀","44₁₀","34₁₀","45₁₀"],"s":[1,0,0,0,0],"w":["Sesuai hasil konversi langkah demi langkah.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Kalikan tiap digit dengan pangkat basisnya dari kanan (pangkat 0, 1, 2, …), lalu jumlahkan."},{"i":4871,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Bilangan desimal 228₁₀ jika diubah ke basis 2 (biner) adalah …","e":"Konsep: desimal ke basis 2: bagi terus dengan 2, catat sisanya, lalu baca sisa dari bawah ke atas.\n1. 228 : 2 = 114 sisa 0\n2. 114 : 2 = 57 sisa 0\n3. 57 : 2 = 28 sisa 1\n4. 28 : 2 = 14 sisa 0\n5. 14 : 2 = 7 sisa 0\n6. 7 : 2 = 3 sisa 1\n7. 3 : 2 = 1 sisa 1\n8. 1 : 2 = 0 sisa 1\n9. Baca sisa dari bawah ke atas.\nJawaban: 11100100₂.\nCara cepat: untuk biner, kurangi dengan pangkat 2 terbesar yang muat (128, 64, 32, …) dan tulis 1 di posisi yang dipakai, 0 di yang dilewati.","o":["1000101000₂","11100110₂","11100011₂","11100100₂","11100101₂"],"s":[0,0,0,1,0],"w":["Ini hasil bila 228₁₀ keliru dibaca sebagai basis 16.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Bagi berulang dengan 2 dan baca sisanya dari bawah ke atas."},{"i":4872,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Bilangan desimal 15₁₀ jika diubah ke basis 16 (heksadesimal) adalah …","e":"Konsep: desimal ke basis 16: bagi terus dengan 16, catat sisanya, lalu baca sisa dari bawah ke atas.\n1. 15 : 16 = 0 sisa 15 (= F)\n2. Baca sisa dari bawah ke atas.\nJawaban: F₁₆.\nCara cepat: cari kelipatan 16 terbesar yang muat, lalu sisa pembagiannya menjadi digit terakhir.","o":["F₁₆","15₁₆","10₁₆","D₁₆","E₁₆"],"s":[1,0,0,0,0],"w":["Sesuai hasil konversi langkah demi langkah.","Ini hasil bila 15₁₀ keliru dibaca sebagai basis 16.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Ini hasil bila 15₁₀ keliru dibaca sebagai basis 8.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Bagi berulang dengan 16 dan baca sisanya dari bawah ke atas."},{"i":4873,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Bilangan oktal 34₈ jika diubah ke basis 10 (desimal) adalah …","e":"Konsep: nilai bilangan basis 8 = jumlah tiap digit dikali 8 pangkat posisinya (posisi paling kanan pangkat 0).\n1. 3×8¹ + 4×8⁰ = 24 + 4 = 28.\nJawaban: 28₁₀.\nCara cepat: hafalkan pangkat 2 (1, 2, 4, 8, 16, 32, 64, 128, 256, 512) dan pangkat 16 (1, 16, 256, 4.096), lalu jumlahkan bobot digit yang tidak nol.","o":["29₁₀","28₁₀","34₁₀","52₁₀","82₁₀"],"s":[0,1,0,0,0],"w":["Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah.","Ini hasil bila 34₈ keliru dibaca sebagai basis 10.","Ini hasil bila 34₈ keliru dibaca sebagai basis 16.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar."],"h":"Kalikan tiap digit dengan pangkat basisnya dari kanan (pangkat 0, 1, 2, …), lalu jumlahkan."},{"i":4874,"k":"skb.ti.bilangan","j":"pilgan","v":3,"q":"Bilangan desimal 349₁₀ jika diubah ke basis 2 (biner) adalah …","e":"Konsep: desimal ke basis 2: bagi terus dengan 2, catat sisanya, lalu baca sisa dari bawah ke atas.\n1. 349 : 2 = 174 sisa 1\n2. 174 : 2 = 87 sisa 0\n3. 87 : 2 = 43 sisa 1\n4. 43 : 2 = 21 sisa 1\n5. 21 : 2 = 10 sisa 1\n6. 10 : 2 = 5 sisa 0\n7. 5 : 2 = 2 sisa 1\n8. 2 : 2 = 1 sisa 0\n9. 1 : 2 = 0 sisa 1\n10. Baca sisa dari bawah ke atas.\nJawaban: 101011101₂.\nCara cepat: untuk biner, kurangi dengan pangkat 2 terbesar yang muat (128, 64, 32, …) dan tulis 1 di posisi yang dipakai, 0 di yang dilewati.","o":["1101001001₂","101011110₂","101011100₂","101110101₂","101011101₂"],"s":[0,0,0,0,1],"w":["Ini hasil bila 349₁₀ keliru dibaca sebagai basis 16.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Sesuai hasil konversi langkah demi langkah."],"h":"Bagi berulang dengan 2 dan baca sisanya dari bawah ke atas."},{"i":4875,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Bilangan heksadesimal DA₁₆ jika diubah ke basis 2 (biner) adalah …","e":"Konsep: satu digit heksadesimal tepat sama dengan 4 bit, jadi konversinya per kelompok tanpa lewat desimal.\n1. Ubah tiap digit menjadi 4 bit: D = 1101, A = 1010.\n2. Gabungkan, lalu buang angka 0 di paling depan.\nJawaban: 11011010₂.\nCara cepat: hafalkan tabel 4 bit (0000 sampai 1111 = 0 sampai F), lalu ubah per kelompok.","o":["11011000₂","11011010₂","11011011₂","11011001₂","11011100₂"],"s":[0,1,0,0,0],"w":["Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Biner, oktal, dan heksadesimal bisa dikonversi per kelompok bit (3 bit untuk oktal, 4 bit untuk heksadesimal)."},{"i":4876,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Bilangan biner 10000101₂ jika diubah ke basis 10 (desimal) adalah …","e":"Konsep: nilai bilangan basis 2 = jumlah tiap digit dikali 2 pangkat posisinya (posisi paling kanan pangkat 0).\n1. 1×2⁷ + 0×2⁶ + 0×2⁵ + 0×2⁴ + 0×2³ + 1×2² + 0×2¹ + 1×2⁰ = 128 + 0 + 0 + 0 + 0 + 4 + 0 + 1 = 133.\nJawaban: 133₁₀.\nCara cepat: hafalkan pangkat 2 (1, 2, 4, 8, 16, 32, 64, 128, 256, 512) dan pangkat 16 (1, 16, 256, 4.096), lalu jumlahkan bobot digit yang tidak nol.","o":["132₁₀","135₁₀","331₁₀","133₁₀","134₁₀"],"s":[0,0,0,1,0],"w":["Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Sesuai hasil konversi langkah demi langkah.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Kalikan tiap digit dengan pangkat basisnya dari kanan (pangkat 0, 1, 2, …), lalu jumlahkan."},{"i":4877,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Bilangan biner 1000111₂ jika diubah ke basis 8 (oktal) adalah …","e":"Konsep: satu digit oktal tepat sama dengan 3 bit, jadi konversinya per kelompok tanpa lewat desimal.\n1. Kelompokkan 3 bit dari kanan: 001 000 111 (tambahkan 0 di kiri bila kurang).\n2. Ubah tiap kelompok: 001 = 1, 000 = 0, 111 = 7.\nJawaban: 107₈.\nCara cepat: hafalkan tabel 3 bit (000 sampai 111 = 0 sampai 7), lalu ubah per kelompok.","o":["110₈","701₈","106₈","111₈","107₈"],"s":[0,0,0,0,1],"w":["Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah."],"h":"Biner, oktal, dan heksadesimal bisa dikonversi per kelompok bit (3 bit untuk oktal, 4 bit untuk heksadesimal)."},{"i":4878,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Bilangan biner 10110000₂ jika diubah ke basis 10 (desimal) adalah …","e":"Konsep: nilai bilangan basis 2 = jumlah tiap digit dikali 2 pangkat posisinya (posisi paling kanan pangkat 0).\n1. 1×2⁷ + 0×2⁶ + 1×2⁵ + 1×2⁴ + 0×2³ + 0×2² + 0×2¹ + 0×2⁰ = 128 + 0 + 32 + 16 + 0 + 0 + 0 + 0 = 176.\nJawaban: 176₁₀.\nCara cepat: hafalkan pangkat 2 (1, 2, 4, 8, 16, 32, 64, 128, 256, 512) dan pangkat 16 (1, 16, 256, 4.096), lalu jumlahkan bobot digit yang tidak nol.","o":["176₁₀","178₁₀","177₁₀","671₁₀","175₁₀"],"s":[1,0,0,0,0],"w":["Sesuai hasil konversi langkah demi langkah.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Kalikan tiap digit dengan pangkat basisnya dari kanan (pangkat 0, 1, 2, …), lalu jumlahkan."},{"i":4879,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Hasil operasi bitwise 11011111 XOR 01010111 adalah …","e":"Konsep: operasi bitwise dikerjakan per kolom bit, tidak ada simpanan (carry). XOR: hasilnya 1 jika kedua bit berbeda.\n1. Bilangan pertama: 11011111\n2. Bilangan kedua: 01010111\n3. Hasil per kolom (XOR): 10001000\nJawaban: 10001000.\nCara cepat: tulis kedua bilangan bertumpuk, lalu periksa kolom demi kolom dari kiri.","o":["01110111","10001010","11011111","01010111","10001000"],"s":[0,0,0,0,1],"w":["Itu kebalikan (NOT) dari jawaban; aturan bitnya terbalik.","Bit ke-7 dari kiri salah dihitung.","Itu hasil OR (hasilnya 1 jika salah satu bit 1), bukan XOR.","Itu hasil AND (hasilnya 1 hanya jika kedua bit 1), bukan XOR.","Dihitung per kolom: hasilnya 1 jika kedua bit berbeda."],"h":"Tulis kedua bilangan bertumpuk dan kerjakan kolom demi kolom. Ingat aturan XOR: hasilnya 1 jika kedua bit berbeda."},{"i":4880,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Representasi komplemen dua 8 bit untuk bilangan −105 adalah …","e":"Konsep: komplemen dua untuk bilangan negatif: tulis nilai positifnya dalam biner, balik semua bit, lalu tambah 1.\n1. 105 dalam 8 bit: 01101001\n2. Balik semua bit (komplemen satu): 10010110\n3. Tambah 1: 10010111\nJawaban: 10010111.\nCara cepat: dari kanan, salin bit sampai bertemu angka 1 pertama (ikut disalin), lalu balik semua bit di kirinya.","o":["10010110","10011000","11101001","01101001","10010111"],"s":[0,0,0,0,1],"w":["Itu komplemen satu (semua bit dibalik) yang belum ditambah 1.","Selisih 1: angka 1 ditambahkan dua kali.","Itu cara tanda-besaran (sign-magnitude): bit kiri 1 lalu nilai biasa, bukan komplemen dua.","Itu 105 positif; tanda minusnya belum diproses.","Bit dibalik semua lalu ditambah 1."],"h":"Tulis nilai positifnya dalam 8 bit, balik semua bit, lalu tambah 1."},{"i":4881,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Bilangan desimal 38₁₀ jika diubah ke basis 2 (biner) adalah …","e":"Konsep: desimal ke basis 2: bagi terus dengan 2, catat sisanya, lalu baca sisa dari bawah ke atas.\n1. 38 : 2 = 19 sisa 0\n2. 19 : 2 = 9 sisa 1\n3. 9 : 2 = 4 sisa 1\n4. 4 : 2 = 2 sisa 0\n5. 2 : 2 = 1 sisa 0\n6. 1 : 2 = 0 sisa 1\n7. Baca sisa dari bawah ke atas.\nJawaban: 100110₂.\nCara cepat: untuk biner, kurangi dengan pangkat 2 terbesar yang muat (128, 64, 32, …) dan tulis 1 di posisi yang dipakai, 0 di yang dilewati.","o":["111000₂","101000₂","100101₂","100110₂","100111₂"],"s":[0,0,0,1,0],"w":["Ini hasil bila 38₁₀ keliru dibaca sebagai basis 16.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Bagi berulang dengan 2 dan baca sisanya dari bawah ke atas."},{"i":4882,"k":"skb.ti.bilangan","j":"pilgan","v":3,"q":"Bilangan biner 111011100₂ jika diubah ke basis 16 (heksadesimal) adalah …","e":"Konsep: satu digit heksadesimal tepat sama dengan 4 bit, jadi konversinya per kelompok tanpa lewat desimal.\n1. Kelompokkan 4 bit dari kanan: 0001 1101 1100 (tambahkan 0 di kiri bila kurang).\n2. Ubah tiap kelompok: 0001 = 1, 1101 = D, 1100 = C.\nJawaban: 1DC₁₆.\nCara cepat: hafalkan tabel 4 bit (0000 sampai 1111 = 0 sampai F), lalu ubah per kelompok.","o":["1DE₁₆","CD1₁₆","1DB₁₆","1DD₁₆","1DC₁₆"],"s":[0,0,0,0,1],"w":["Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah."],"h":"Biner, oktal, dan heksadesimal bisa dikonversi per kelompok bit (3 bit untuk oktal, 4 bit untuk heksadesimal)."},{"i":4883,"k":"skb.ti.bilangan","j":"pilgan","v":3,"q":"Bilangan 8 bit 11100111 dalam format komplemen dua bernilai desimal …","e":"Konsep: pada komplemen dua 8 bit, bit paling kiri bernilai −128. Nilai = −128 + jumlah bobot bit lainnya.\n1. Bit paling kiri 1, jadi bilangannya negatif.\n2. Balik semua bit: 00011000\n3. Tambah 1: 00011001 = 25\n4. Jadi nilainya −25.\nJawaban: −25.\nCara cepat: hitung langsung: −128 + 103 = −25.","o":["−103","231","−24","−25","25"],"s":[0,0,0,1,0],"w":["Itu cara tanda-besaran: bit kiri hanya dianggap tanda, sisanya dibaca biasa.","Itu nilai bila bit dibaca tanpa tanda (unsigned).","Itu cara membaca komplemen satu: setelah bit dibalik, masih harus ditambah 1.","Bit kiri 1 berarti negatif; dibalik lalu ditambah 1 memberi besarnya.","Bit paling kiri 1, jadi bilangannya negatif."],"h":"Bit paling kiri pada komplemen dua 8 bit berbobot −128; bit lain berbobot positif seperti biasa."},{"i":4884,"k":"skb.ti.bilangan","j":"pilgan","v":3,"q":"Bilangan desimal 933₁₀ jika diubah ke basis 2 (biner) adalah …","e":"Konsep: desimal ke basis 2: bagi terus dengan 2, catat sisanya, lalu baca sisa dari bawah ke atas.\n1. 933 : 2 = 466 sisa 1\n2. 466 : 2 = 233 sisa 0\n3. 233 : 2 = 116 sisa 1\n4. 116 : 2 = 58 sisa 0\n5. 58 : 2 = 29 sisa 0\n6. 29 : 2 = 14 sisa 1\n7. 14 : 2 = 7 sisa 0\n8. 7 : 2 = 3 sisa 1\n9. 3 : 2 = 1 sisa 1\n10. 1 : 2 = 0 sisa 1\n11. Baca sisa dari bawah ke atas.\nJawaban: 1110100101₂.\nCara cepat: untuk biner, kurangi dengan pangkat 2 terbesar yang muat (128, 64, 32, …) dan tulis 1 di posisi yang dipakai, 0 di yang dilewati.","o":["1010010111₂","1110100100₂","1110100110₂","100100110011₂","1110100101₂"],"s":[0,0,0,0,1],"w":["Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Ini hasil bila 933₁₀ keliru dibaca sebagai basis 16.","Sesuai hasil konversi langkah demi langkah."],"h":"Bagi berulang dengan 2 dan baca sisanya dari bawah ke atas."},{"i":4885,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Bilangan oktal 45₈ jika diubah ke basis 10 (desimal) adalah …","e":"Konsep: nilai bilangan basis 8 = jumlah tiap digit dikali 8 pangkat posisinya (posisi paling kanan pangkat 0).\n1. 4×8¹ + 5×8⁰ = 32 + 5 = 37.\nJawaban: 37₁₀.\nCara cepat: hafalkan pangkat 2 (1, 2, 4, 8, 16, 32, 64, 128, 256, 512) dan pangkat 16 (1, 16, 256, 4.096), lalu jumlahkan bobot digit yang tidak nol.","o":["69₁₀","73₁₀","45₁₀","37₁₀","38₁₀"],"s":[0,0,0,1,0],"w":["Ini hasil bila 45₈ keliru dibaca sebagai basis 16.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Ini hasil bila 45₈ keliru dibaca sebagai basis 10.","Sesuai hasil konversi langkah demi langkah.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Kalikan tiap digit dengan pangkat basisnya dari kanan (pangkat 0, 1, 2, …), lalu jumlahkan."},{"i":4886,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Bilangan biner 1100011₂ jika diubah ke basis 10 (desimal) adalah …","e":"Konsep: nilai bilangan basis 2 = jumlah tiap digit dikali 2 pangkat posisinya (posisi paling kanan pangkat 0).\n1. 1×2⁶ + 1×2⁵ + 0×2⁴ + 0×2³ + 0×2² + 1×2¹ + 1×2⁰ = 64 + 32 + 0 + 0 + 0 + 2 + 1 = 99.\nJawaban: 99₁₀.\nCara cepat: hafalkan pangkat 2 (1, 2, 4, 8, 16, 32, 64, 128, 256, 512) dan pangkat 16 (1, 16, 256, 4.096), lalu jumlahkan bobot digit yang tidak nol.","o":["101₁₀","99₁₀","97₁₀","98₁₀","100₁₀"],"s":[0,1,0,0,0],"w":["Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Kalikan tiap digit dengan pangkat basisnya dari kanan (pangkat 0, 1, 2, …), lalu jumlahkan."},{"i":4887,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Bilangan heksadesimal A₁₆ jika diubah ke basis 10 (desimal) adalah …","e":"Konsep: nilai bilangan basis 16 = jumlah tiap digit dikali 16 pangkat posisinya (posisi paling kanan pangkat 0).\n1. 10×16⁰ = 10 = 10.\nJawaban: 10₁₀.\nCara cepat: hafalkan pangkat 2 (1, 2, 4, 8, 16, 32, 64, 128, 256, 512) dan pangkat 16 (1, 16, 256, 4.096), lalu jumlahkan bobot digit yang tidak nol.","o":["12₁₀","8₁₀","9₁₀","10₁₀","11₁₀"],"s":[0,0,0,1,0],"w":["Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Kalikan tiap digit dengan pangkat basisnya dari kanan (pangkat 0, 1, 2, …), lalu jumlahkan."},{"i":4888,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Bilangan biner 110100₂ jika diubah ke basis 10 (desimal) adalah …","e":"Konsep: nilai bilangan basis 2 = jumlah tiap digit dikali 2 pangkat posisinya (posisi paling kanan pangkat 0).\n1. 1×2⁵ + 1×2⁴ + 0×2³ + 1×2² + 0×2¹ + 0×2⁰ = 32 + 16 + 0 + 4 + 0 + 0 = 52.\nJawaban: 52₁₀.\nCara cepat: hafalkan pangkat 2 (1, 2, 4, 8, 16, 32, 64, 128, 256, 512) dan pangkat 16 (1, 16, 256, 4.096), lalu jumlahkan bobot digit yang tidak nol.","o":["51₁₀","53₁₀","25₁₀","52₁₀","54₁₀"],"s":[0,0,0,1,0],"w":["Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Sesuai hasil konversi langkah demi langkah.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Kalikan tiap digit dengan pangkat basisnya dari kanan (pangkat 0, 1, 2, …), lalu jumlahkan."},{"i":4889,"k":"skb.ti.bilangan","j":"pilgan","v":3,"q":"Bilangan biner 1101111001₂ jika diubah ke basis 8 (oktal) adalah …","e":"Konsep: satu digit oktal tepat sama dengan 3 bit, jadi konversinya per kelompok tanpa lewat desimal.\n1. Kelompokkan 3 bit dari kanan: 001 101 111 001 (tambahkan 0 di kiri bila kurang).\n2. Ubah tiap kelompok: 001 = 1, 101 = 5, 111 = 7, 001 = 1.\nJawaban: 1571₈.\nCara cepat: hafalkan tabel 3 bit (000 sampai 111 = 0 sampai 7), lalu ubah per kelompok.","o":["1751₈","1572₈","1571₈","1570₈","1573₈"],"s":[0,0,1,0,0],"w":["Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Biner, oktal, dan heksadesimal bisa dikonversi per kelompok bit (3 bit untuk oktal, 4 bit untuk heksadesimal)."},{"i":4890,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Hasil operasi bitwise 11100111 OR 10101011 adalah …","e":"Konsep: operasi bitwise dikerjakan per kolom bit, tidak ada simpanan (carry). OR: hasilnya 1 jika salah satu bit 1.\n1. Bilangan pertama: 11100111\n2. Bilangan kedua: 10101011\n3. Hasil per kolom (OR): 11101111\nJawaban: 11101111.\nCara cepat: tulis kedua bilangan bertumpuk, lalu periksa kolom demi kolom dari kiri.","o":["11101110","10100011","11101111","00010000","01001100"],"s":[0,0,1,0,0],"w":["Bit ke-8 dari kiri salah dihitung.","Itu hasil AND (hasilnya 1 hanya jika kedua bit 1), bukan OR.","Dihitung per kolom: hasilnya 1 jika salah satu bit 1.","Itu kebalikan (NOT) dari jawaban; aturan bitnya terbalik.","Itu hasil XOR (hasilnya 1 jika kedua bit berbeda), bukan OR."],"h":"Tulis kedua bilangan bertumpuk dan kerjakan kolom demi kolom. Ingat aturan OR: hasilnya 1 jika salah satu bit 1."},{"i":4891,"k":"skb.ti.bilangan","j":"pilgan","v":3,"q":"Bilangan desimal 3403₁₀ jika diubah ke basis 16 (heksadesimal) adalah …","e":"Konsep: desimal ke basis 16: bagi terus dengan 16, catat sisanya, lalu baca sisa dari bawah ke atas.\n1. 3403 : 16 = 212 sisa 11 (= B)\n2. 212 : 16 = 13 sisa 4\n3. 13 : 16 = 0 sisa 13 (= D)\n4. Baca sisa dari bawah ke atas.\nJawaban: D4B₁₆.\nCara cepat: cari kelipatan 16 terbesar yang muat, lalu sisa pembagiannya menjadi digit terakhir.","o":["3403₁₆","B4D₁₆","D4C₁₆","D4B₁₆","703₁₆"],"s":[0,0,0,1,0],"w":["Ini hasil bila 3403₁₀ keliru dibaca sebagai basis 16.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah.","Ini hasil bila 3403₁₀ keliru dibaca sebagai basis 8."],"h":"Bagi berulang dengan 16 dan baca sisanya dari bawah ke atas."},{"i":4892,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Bilangan biner 111010₂ jika diubah ke basis 8 (oktal) adalah …","e":"Konsep: satu digit oktal tepat sama dengan 3 bit, jadi konversinya per kelompok tanpa lewat desimal.\n1. Kelompokkan 3 bit dari kanan: 111 010 (tambahkan 0 di kiri bila kurang).\n2. Ubah tiap kelompok: 111 = 7, 010 = 2.\nJawaban: 72₈.\nCara cepat: hafalkan tabel 3 bit (000 sampai 111 = 0 sampai 7), lalu ubah per kelompok.","o":["27₈","73₈","71₈","72₈","74₈"],"s":[0,0,0,1,0],"w":["Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah.","Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Biner, oktal, dan heksadesimal bisa dikonversi per kelompok bit (3 bit untuk oktal, 4 bit untuk heksadesimal)."},{"i":4893,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Representasi komplemen dua 8 bit untuk bilangan −67 adalah …","e":"Konsep: komplemen dua untuk bilangan negatif: tulis nilai positifnya dalam biner, balik semua bit, lalu tambah 1.\n1. 67 dalam 8 bit: 01000011\n2. Balik semua bit (komplemen satu): 10111100\n3. Tambah 1: 10111101\nJawaban: 10111101.\nCara cepat: dari kanan, salin bit sampai bertemu angka 1 pertama (ikut disalin), lalu balik semua bit di kirinya.","o":["10111110","01000011","10111100","11000011","10111101"],"s":[0,0,0,0,1],"w":["Selisih 1: angka 1 ditambahkan dua kali.","Itu 67 positif; tanda minusnya belum diproses.","Itu komplemen satu (semua bit dibalik) yang belum ditambah 1.","Itu cara tanda-besaran (sign-magnitude): bit kiri 1 lalu nilai biasa, bukan komplemen dua.","Bit dibalik semua lalu ditambah 1."],"h":"Tulis nilai positifnya dalam 8 bit, balik semua bit, lalu tambah 1."},{"i":4894,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Bilangan desimal 225₁₀ jika diubah ke basis 2 (biner) adalah …","e":"Konsep: desimal ke basis 2: bagi terus dengan 2, catat sisanya, lalu baca sisa dari bawah ke atas.\n1. 225 : 2 = 112 sisa 1\n2. 112 : 2 = 56 sisa 0\n3. 56 : 2 = 28 sisa 0\n4. 28 : 2 = 14 sisa 0\n5. 14 : 2 = 7 sisa 0\n6. 7 : 2 = 3 sisa 1\n7. 3 : 2 = 1 sisa 1\n8. 1 : 2 = 0 sisa 1\n9. Baca sisa dari bawah ke atas.\nJawaban: 11100001₂.\nCara cepat: untuk biner, kurangi dengan pangkat 2 terbesar yang muat (128, 64, 32, …) dan tulis 1 di posisi yang dipakai, 0 di yang dilewati.","o":["10010101₂","11100001₂","1000100101₂","11100010₂","10000111₂"],"s":[0,1,0,0,0],"w":["Ini hasil bila 225₁₀ keliru dibaca sebagai basis 8.","Sesuai hasil konversi langkah demi langkah.","Ini hasil bila 225₁₀ keliru dibaca sebagai basis 16.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar."],"h":"Bagi berulang dengan 2 dan baca sisanya dari bawah ke atas."},{"i":4895,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Bilangan desimal 57₁₀ jika diubah ke basis 2 (biner) adalah …","e":"Konsep: desimal ke basis 2: bagi terus dengan 2, catat sisanya, lalu baca sisa dari bawah ke atas.\n1. 57 : 2 = 28 sisa 1\n2. 28 : 2 = 14 sisa 0\n3. 14 : 2 = 7 sisa 0\n4. 7 : 2 = 3 sisa 1\n5. 3 : 2 = 1 sisa 1\n6. 1 : 2 = 0 sisa 1\n7. Baca sisa dari bawah ke atas.\nJawaban: 111001₂.\nCara cepat: untuk biner, kurangi dengan pangkat 2 terbesar yang muat (128, 64, 32, …) dan tulis 1 di posisi yang dipakai, 0 di yang dilewati.","o":["1010111₂","111010₂","100111₂","111001₂","101111₂"],"s":[0,0,0,1,0],"w":["Ini hasil bila 57₁₀ keliru dibaca sebagai basis 16.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Sesuai hasil konversi langkah demi langkah.","Ini hasil bila 57₁₀ keliru dibaca sebagai basis 8."],"h":"Bagi berulang dengan 2 dan baca sisanya dari bawah ke atas."},{"i":4896,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Bilangan heksadesimal 2F₁₆ jika diubah ke basis 10 (desimal) adalah …","e":"Konsep: nilai bilangan basis 16 = jumlah tiap digit dikali 16 pangkat posisinya (posisi paling kanan pangkat 0).\n1. 2×16¹ + 15×16⁰ = 32 + 15 = 47.\nJawaban: 47₁₀.\nCara cepat: hafalkan pangkat 2 (1, 2, 4, 8, 16, 32, 64, 128, 256, 512) dan pangkat 16 (1, 16, 256, 4.096), lalu jumlahkan bobot digit yang tidak nol.","o":["49₁₀","74₁₀","47₁₀","46₁₀","48₁₀"],"s":[0,0,1,0,0],"w":["Meleset 2 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Sesuai hasil konversi langkah demi langkah.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Kalikan tiap digit dengan pangkat basisnya dari kanan (pangkat 0, 1, 2, …), lalu jumlahkan."},{"i":4897,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Bilangan desimal 427₁₀ jika diubah ke basis 8 (oktal) adalah …","e":"Konsep: desimal ke basis 8: bagi terus dengan 8, catat sisanya, lalu baca sisa dari bawah ke atas.\n1. 427 : 8 = 53 sisa 3\n2. 53 : 8 = 6 sisa 5\n3. 6 : 8 = 0 sisa 6\n4. Baca sisa dari bawah ke atas.\nJawaban: 653₈.\nCara cepat: cari kelipatan 8 terbesar yang muat, lalu sisa pembagiannya menjadi digit terakhir.","o":["653₈","356₈","2047₈","427₈","654₈"],"s":[1,0,0,0,0],"w":["Sesuai hasil konversi langkah demi langkah.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Ini hasil bila 427₁₀ keliru dibaca sebagai basis 16.","Ini hasil bila 427₁₀ keliru dibaca sebagai basis 8.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Bagi berulang dengan 8 dan baca sisanya dari bawah ke atas."},{"i":4898,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Hasil operasi bitwise 00010000 AND 00111000 adalah …","e":"Konsep: operasi bitwise dikerjakan per kolom bit, tidak ada simpanan (carry). AND: hasilnya 1 hanya jika kedua bit 1.\n1. Bilangan pertama: 00010000\n2. Bilangan kedua: 00111000\n3. Hasil per kolom (AND): 00010000\nJawaban: 00010000.\nCara cepat: tulis kedua bilangan bertumpuk, lalu periksa kolom demi kolom dari kiri.","o":["00010000","00111000","11101111","00101000","00010100"],"s":[1,0,0,0,0],"w":["Dihitung per kolom: hasilnya 1 hanya jika kedua bit 1.","Itu hasil OR (hasilnya 1 jika salah satu bit 1), bukan AND.","Itu kebalikan (NOT) dari jawaban; aturan bitnya terbalik.","Itu hasil XOR (hasilnya 1 jika kedua bit berbeda), bukan AND.","Bit ke-6 dari kiri salah dihitung."],"h":"Tulis kedua bilangan bertumpuk dan kerjakan kolom demi kolom. Ingat aturan AND: hasilnya 1 hanya jika kedua bit 1."},{"i":4899,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Bilangan oktal 16₈ jika diubah ke basis 10 (desimal) adalah …","e":"Konsep: nilai bilangan basis 8 = jumlah tiap digit dikali 8 pangkat posisinya (posisi paling kanan pangkat 0).\n1. 1×8¹ + 6×8⁰ = 8 + 6 = 14.\nJawaban: 14₁₀.\nCara cepat: hafalkan pangkat 2 (1, 2, 4, 8, 16, 32, 64, 128, 256, 512) dan pangkat 16 (1, 16, 256, 4.096), lalu jumlahkan bobot digit yang tidak nol.","o":["15₁₀","22₁₀","14₁₀","16₁₀","41₁₀"],"s":[0,0,1,0,0],"w":["Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Ini hasil bila 16₈ keliru dibaca sebagai basis 16.","Sesuai hasil konversi langkah demi langkah.","Ini hasil bila 16₈ keliru dibaca sebagai basis 10.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar."],"h":"Kalikan tiap digit dengan pangkat basisnya dari kanan (pangkat 0, 1, 2, …), lalu jumlahkan."},{"i":4900,"k":"skb.ti.bilangan","j":"pilgan","v":3,"q":"Bilangan oktal 1054₈ jika diubah ke basis 2 (biner) adalah …","e":"Konsep: satu digit oktal tepat sama dengan 3 bit, jadi konversinya per kelompok tanpa lewat desimal.\n1. Ubah tiap digit menjadi 3 bit: 1 = 001, 0 = 000, 5 = 101, 4 = 100.\n2. Gabungkan, lalu buang angka 0 di paling depan.\nJawaban: 1000101100₂.\nCara cepat: hafalkan tabel 3 bit (000 sampai 111 = 0 sampai 7), lalu ubah per kelompok.","o":["1000101100₂","1000101101₂","10000011110₂","1000001010100₂","1000101011₂"],"s":[1,0,0,0,0],"w":["Sesuai hasil konversi langkah demi langkah.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Ini hasil bila 1054₈ keliru dibaca sebagai basis 10.","Ini hasil bila 1054₈ keliru dibaca sebagai basis 16.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Biner, oktal, dan heksadesimal bisa dikonversi per kelompok bit (3 bit untuk oktal, 4 bit untuk heksadesimal)."},{"i":4901,"k":"skb.ti.bilangan","j":"pilgan","v":3,"q":"Bilangan desimal 3435₁₀ jika diubah ke basis 16 (heksadesimal) adalah …","e":"Konsep: desimal ke basis 16: bagi terus dengan 16, catat sisanya, lalu baca sisa dari bawah ke atas.\n1. 3435 : 16 = 214 sisa 11 (= B)\n2. 214 : 16 = 13 sisa 6\n3. 13 : 16 = 0 sisa 13 (= D)\n4. Baca sisa dari bawah ke atas.\nJawaban: D6B₁₆.\nCara cepat: cari kelipatan 16 terbesar yang muat, lalu sisa pembagiannya menjadi digit terakhir.","o":["71D₁₆","D6C₁₆","B6D₁₆","3435₁₆","D6B₁₆"],"s":[0,0,0,0,1],"w":["Ini hasil bila 3435₁₀ keliru dibaca sebagai basis 8.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Ini hasil bila 3435₁₀ keliru dibaca sebagai basis 16.","Sesuai hasil konversi langkah demi langkah."],"h":"Bagi berulang dengan 16 dan baca sisanya dari bawah ke atas."},{"i":4902,"k":"skb.ti.bilangan","j":"pilgan","v":3,"q":"Bilangan oktal 6346₈ jika diubah ke basis 10 (desimal) adalah …","e":"Konsep: nilai bilangan basis 8 = jumlah tiap digit dikali 8 pangkat posisinya (posisi paling kanan pangkat 0).\n1. 6×8³ + 3×8² + 4×8¹ + 6×8⁰ = 3072 + 192 + 32 + 6 = 3302.\nJawaban: 3302₁₀.\nCara cepat: hafalkan pangkat 2 (1, 2, 4, 8, 16, 32, 64, 128, 256, 512) dan pangkat 16 (1, 16, 256, 4.096), lalu jumlahkan bobot digit yang tidak nol.","o":["2033₁₀","3302₁₀","6346₁₀","3303₁₀","25414₁₀"],"s":[0,1,0,0,0],"w":["Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Sesuai hasil konversi langkah demi langkah.","Ini hasil bila 6346₈ keliru dibaca sebagai basis 10.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Ini hasil bila 6346₈ keliru dibaca sebagai basis 16."],"h":"Kalikan tiap digit dengan pangkat basisnya dari kanan (pangkat 0, 1, 2, …), lalu jumlahkan."},{"i":4903,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Bilangan oktal 106₈ jika diubah ke basis 2 (biner) adalah …","e":"Konsep: satu digit oktal tepat sama dengan 3 bit, jadi konversinya per kelompok tanpa lewat desimal.\n1. Ubah tiap digit menjadi 3 bit: 1 = 001, 0 = 000, 6 = 110.\n2. Gabungkan, lalu buang angka 0 di paling depan.\nJawaban: 1000110₂.\nCara cepat: hafalkan tabel 3 bit (000 sampai 111 = 0 sampai 7), lalu ubah per kelompok.","o":["100000110₂","1000101₂","1000110₂","1101010₂","1000111₂"],"s":[0,0,1,0,0],"w":["Ini hasil bila 106₈ keliru dibaca sebagai basis 16.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah.","Ini hasil bila 106₈ keliru dibaca sebagai basis 10.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Biner, oktal, dan heksadesimal bisa dikonversi per kelompok bit (3 bit untuk oktal, 4 bit untuk heksadesimal)."},{"i":4904,"k":"skb.ti.bilangan","j":"pilgan","v":3,"q":"Bilangan 8 bit 11011100 dalam format komplemen dua bernilai desimal …","e":"Konsep: pada komplemen dua 8 bit, bit paling kiri bernilai −128. Nilai = −128 + jumlah bobot bit lainnya.\n1. Bit paling kiri 1, jadi bilangannya negatif.\n2. Balik semua bit: 00100011\n3. Tambah 1: 00100100 = 36\n4. Jadi nilainya −36.\nJawaban: −36.\nCara cepat: hitung langsung: −128 + 92 = −36.","o":["220","−92","36","−36","−35"],"s":[0,0,0,1,0],"w":["Itu nilai bila bit dibaca tanpa tanda (unsigned).","Itu cara tanda-besaran: bit kiri hanya dianggap tanda, sisanya dibaca biasa.","Bit paling kiri 1, jadi bilangannya negatif.","Bit kiri 1 berarti negatif; dibalik lalu ditambah 1 memberi besarnya.","Itu cara membaca komplemen satu: setelah bit dibalik, masih harus ditambah 1."],"h":"Bit paling kiri pada komplemen dua 8 bit berbobot −128; bit lain berbobot positif seperti biasa."},{"i":4905,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Hasil operasi bitwise 10111000 OR 01110111 adalah …","e":"Konsep: operasi bitwise dikerjakan per kolom bit, tidak ada simpanan (carry). OR: hasilnya 1 jika salah satu bit 1.\n1. Bilangan pertama: 10111000\n2. Bilangan kedua: 01110111\n3. Hasil per kolom (OR): 11111111\nJawaban: 11111111.\nCara cepat: tulis kedua bilangan bertumpuk, lalu periksa kolom demi kolom dari kiri.","o":["00110000","11001111","11111110","11111111","00000000"],"s":[0,0,0,1,0],"w":["Itu hasil AND (hasilnya 1 hanya jika kedua bit 1), bukan OR.","Itu hasil XOR (hasilnya 1 jika kedua bit berbeda), bukan OR.","Bit ke-8 dari kiri salah dihitung.","Dihitung per kolom: hasilnya 1 jika salah satu bit 1.","Itu kebalikan (NOT) dari jawaban; aturan bitnya terbalik."],"h":"Tulis kedua bilangan bertumpuk dan kerjakan kolom demi kolom. Ingat aturan OR: hasilnya 1 jika salah satu bit 1."},{"i":4906,"k":"skb.ti.bilangan","j":"pilgan","v":2,"q":"Bilangan desimal 386₁₀ jika diubah ke basis 8 (oktal) adalah …","e":"Konsep: desimal ke basis 8: bagi terus dengan 8, catat sisanya, lalu baca sisa dari bawah ke atas.\n1. 386 : 8 = 48 sisa 2\n2. 48 : 8 = 6 sisa 0\n3. 6 : 8 = 0 sisa 6\n4. Baca sisa dari bawah ke atas.\nJawaban: 602₈.\nCara cepat: cari kelipatan 8 terbesar yang muat, lalu sisa pembagiannya menjadi digit terakhir.","o":["1606₈","601₈","602₈","206₈","603₈"],"s":[0,0,1,0,0],"w":["Ini hasil bila 386₁₀ keliru dibaca sebagai basis 16.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Sesuai hasil konversi langkah demi langkah.","Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung."],"h":"Bagi berulang dengan 8 dan baca sisanya dari bawah ke atas."},{"i":4907,"k":"skb.ti.bilangan","j":"pilgan","v":3,"q":"Bilangan oktal 4143₈ jika diubah ke basis 10 (desimal) adalah …","e":"Konsep: nilai bilangan basis 8 = jumlah tiap digit dikali 8 pangkat posisinya (posisi paling kanan pangkat 0).\n1. 4×8³ + 1×8² + 4×8¹ + 3×8⁰ = 2048 + 64 + 32 + 3 = 2147.\nJawaban: 2147₁₀.\nCara cepat: hafalkan pangkat 2 (1, 2, 4, 8, 16, 32, 64, 128, 256, 512) dan pangkat 16 (1, 16, 256, 4.096), lalu jumlahkan bobot digit yang tidak nol.","o":["7412₁₀","2148₁₀","16707₁₀","4143₁₀","2147₁₀"],"s":[0,0,0,0,1],"w":["Digitnya terbalik. Sisa pembagian dibaca dari bawah ke atas; digit paling kiri bernilai paling besar.","Meleset 1 dari nilai sebenarnya: ada bobot posisi atau sisa bagi yang salah hitung.","Ini hasil bila 4143₈ keliru dibaca sebagai basis 16.","Ini hasil bila 4143₈ keliru dibaca sebagai basis 10.","Sesuai hasil konversi langkah demi langkah."],"h":"Kalikan tiap digit dengan pangkat basisnya dari kanan (pangkat 0, 1, 2, …), lalu jumlahkan."},{"i":4908,"k":"skb.ti.bilangan","j":"pilgan","v":3,"q":"Bilangan 8 bit 11000011 dalam format komplemen dua bernilai desimal …","e":"Konsep: pada komplemen dua 8 bit, bit paling kiri bernilai −128. Nilai = −128 + jumlah bobot bit lainnya.\n1. Bit paling kiri 1, jadi bilangannya negatif.\n2. Balik semua bit: 00111100\n3. Tambah 1: 00111101 = 61\n4. Jadi nilainya −61.\nJawaban: −61.\nCara cepat: hitung langsung: −128 + 67 = −61.","o":["−60","−61","−67","61","195"],"s":[0,1,0,0,0],"w":["Itu cara membaca komplemen satu: setelah bit dibalik, masih harus ditambah 1.","Bit kiri 1 berarti negatif; dibalik lalu ditambah 1 memberi besarnya.","Itu cara tanda-besaran: bit kiri hanya dianggap tanda, sisanya dibaca biasa.","Bit paling kiri 1, jadi bilangannya negatif.","Itu nilai bila bit dibaca tanpa tanda (unsigned)."],"h":"Bit paling kiri pada komplemen dua 8 bit berbobot −128; bit lain berbobot positif seperti biasa."},{"i":4909,"k":"skb.ti.bilangan","j":"pilgan","v":1,"q":"Hasil operasi bitwise 00111110 AND 00011001 adalah …","e":"Konsep: operasi bitwise dikerjakan per kolom bit, tidak ada simpanan (carry). AND: hasilnya 1 hanya jika kedua bit 1.\n1. Bilangan pertama: 00111110\n2. Bilangan kedua: 00011001\n3. Hasil per kolom (AND): 00011000\nJawaban: 00011000.\nCara cepat: tulis kedua bilangan bertumpuk, lalu periksa kolom demi kolom dari kiri.","o":["00111111","11100111","00100111","00011000","10011000"],"s":[0,0,0,1,0],"w":["Itu hasil OR (hasilnya 1 jika salah satu bit 1), bukan AND.","Itu kebalikan (NOT) dari jawaban; aturan bitnya terbalik.","Itu hasil XOR (hasilnya 1 jika kedua bit berbeda), bukan AND.","Dihitung per kolom: hasilnya 1 hanya jika kedua bit 1.","Bit ke-1 dari kiri salah dihitung."],"h":"Tulis kedua bilangan bertumpuk dan kerjakan kolom demi kolom. Ingat aturan AND: hasilnya 1 hanya jika kedua bit 1."}];
